        and DATE_FORMAT(report.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}


        and DATE_FORMAT(report.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}


        and DATE_FORMAT(report.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart,jdbcType=VARCHAR}


        and DATE_FORMAT(report.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd,jdbcType=VARCHAR}


        AND DATE_FORMAT(report.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


        and DATE_FORMAT(report.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}


        and report.TERMID = #{termId}


ORDER BY report.PBC_SUBMIT_DEADLINE ASC, report.UPDATE_TIME DESC

