select
PMAP.POSUUID, PMAP.PRODID, PMAP.ORG_CODE, PMAP.POSITION_TYPE, PMAP.CHL_ID, PMAP.ASSET_CODE, PMAP.ASSET_TYPE1, case when ASSETINFO.ASSET_TYPE2='1108' THEN 'R03' ELSE PMAP.ASSET_TYPE2 END ASSET_TYPE2, PMAP.ASSET_TYPE3, PMAP.STARTDATE, PMAP.ENDDATE, PMAP.BOOKDATE, PMAP.CCY, PMAP.AMT, PMAP.INT_AMT, PMAP.END_DAYS, PMAP.BAL_FLAG,PMAP.RATING, ASSETINFO.BANK_SEC_CAPITAL, ASSETINFO.BANK_SEC_PERPETUAL, ASSETINFO.BANK_SEC_PREFER, ASSETINFO.IS_PERPETUAL, ASSETINFO.ORG_ASSET_TYPE3, ASSETINFO.BANK_CAPITAL, minfo.PARTY_TYPE1, PMAP.END_DAYS_PBC,
PMAP.REC_INT_AMT from PBC_MONTH_ASSET_POSITION PMAP
left join CHB_ASSET_INFO ASSETINFO ON ASSETINFO.ASSET_CODE = PMAP.ASSET_CODE and ASSETINFO.status in('E','M') left join MST_CUSTOMER_INFO_ADD minfo on minfo.CUSTOMER_ID =ASSETINFO.CHB_ISSUER_ID where DATE_FORMAT(ENDDATE,'%Y-%m-%d') = #{bookDate,jdbcType=VARCHAR}
